fn remove_duplicates(nums: &Vec<i32>) -> usize {
    // If the array is empty, there are no distinct values.
    if nums.is_empty() {
        return 0;
    }

    // We know there's at least one element, so start count at 1.
    let mut count: usize = 1;
    // Track the last seen value.
    let mut prev: i32 = nums[0];

    // Iterate over the rest of the elements.
    for &v in nums.iter().skip(1) {
        // Whenever we see a new value, increment the distinct count
        // and update `prev`.
        if v != prev {
            count += 1;
            prev = v;
        }
    }

    count
}

